/** The command that reproduces the fork by hand. */
export function forkCommand(sourceSession: string, sessionId: string, args: string): string {
	return `pi --fork ${sourceSession} --session-id ${sessionId} ${quote(learnPrompt(args))}`;
}

export interface NoticeInput {
	sessionId: string;
	sourceSession: string;
	args: string;
	/** The dashboard accepted `POST /api/forks`. */
	registered: boolean;
	/** `resume` echoed by the dashboard, e.g. `pi --session <id>`. */
	resume?: string;
	/** Why the dashboard refused the fork (a 4xx/5xx), shown so the fallback is not silent. */
	refused?: string;
	/** The project whose empty pane took the fork; absent = the floating shell set. */
	projectName?: string;
	/** That pane's `#n`; 0 or absent when not numbered yet. */
	pane?: number;
}

/** Where the dashboard put the fork: a project's pane (`#n`), the project, or the floating set. */
export function dashboardPlace(projectName?: string, pane?: number): string {
	if (!projectName) return "dashboard floating";
	return pane ? `dashboard ${projectName} #${pane}` : `dashboard ${projectName}`;
}

/**
 * One line for the TUI: the fork id always, plus `· dashboard Forks` when the dashboard owns
 * the process, or the full command to run when it does not.
 */
export function buildNotice(input: NoticeInput): string {
	const resume = input.resume?.trim() || `pi --session ${input.sessionId}`;
	const head = `learn → fork ${input.sessionId} · ${resume}`;
	if (input.registered) return `${head} · ${dashboardPlace(input.projectName, input.pane)}`;
	const why = input.refused ? ` · dashboard refused: ${input.refused}` : "";
	return `${head} · run: ${forkCommand(input.sourceSession, input.sessionId, input.args)}${why}`;
}

export interface ForkRequest {
	cwd: string;
	/** Current session id: the fork continues its history. */
	sourceSession: string;
	/** Id chosen here and pinned with `--session-id`, so the notice names the real session. */
	sessionId: string;
	args: string;
}

